ST.xhtml:p:
(*送料轴点动*)
IF bJogFast THEN
  g_General1_Jog.Mode := 1;
ELSE
  g_General1_Jog.Mode := 0;
END_IF;

g_General1_Jog.JogForward := bGeneral1JogForward;
g_General1_Jog.JogBackwards := bGeneral1BackForward;
g_noGeneral1Errorid := g_General1_Jog.errorid;

(*顶料轴点动*)
IF bJogFast THEN
  g_General2_Jog.Mode := 1;
ELSE
  g_General2_Jog.Mode := 0;
END_IF;

g_General2_Jog.JogForward := bGeneral2JogForward;
g_General2_Jog.JogBackwards := bGeneral2BackForward;
g_noGeneral2Errorid := g_General2_Jog.errorid;

IF g_bPlcResetBuffer THEN
  bGeneral1JogForward := FALSE;
  bGeneral1BackForward := FALSE;
  bGeneral2JogForward := FALSE;
  bGeneral2BackForward := FALSE;
END_IF;
